"""sim/results/*.json (from mujoco_conveyor.py) -> sim/results/RESULTS.md: one table row per scenario, one column
per check, PASS/FAIL with the numbers. Plain Python, either venv."""
import json
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent


def main(results=HERE / "results"):
    rows = {p.stem: json.loads(p.read_text()) for p in sorted(Path(results).glob("*.json"))}
    if not rows:
        sys.exit(f"no results in {results}")
    out = ["# Scenario results", "",
           "Generated by `sim/report.py` from `sim/results/*.json`. Friction coefficients are assumptions "
           "(see the assumptions in sim/mujoco_conveyor.py).", ""]
    out += ["| scenario | setup | mass g | v m/min | mu belt / rail | verdict |", "|---|---|---|---|---|---|"]
    for n, r in rows.items():
        out.append(f"| {n} | {r['note']} | {r['mass_g']:.0f} | {r['speed_m_min']:g} | {r['mu_belt']:g} / "
                   f"{r['mu_guide']:g} | {'PASS' if r['pass'] else '**FAIL**'} |")
    out += ["", "## Checks", ""]
    for n, r in rows.items():
        out.append(f"### {n}: {'PASS' if r['pass'] else 'FAIL'}")
        out.append("")
        for k, c in r["checks"].items():
            out.append(f"- {'PASS' if c['pass'] else '**FAIL**'} {k}: {c['detail']}")
        out.append(f"- board contacts sampled: {', '.join(f'{k} {v}' for k, v in r['contacts_seen'].items())}")
        out.append("")
    (Path(results) / "RESULTS.md").write_text("\n".join(out) + "\n")
    print(f"wrote {Path(results) / 'RESULTS.md'}")


if __name__ == "__main__":
    main(*sys.argv[1:])
